-- Extend the existing fallback table rather than replacing it: older strings
-- and missing translations retain exactly the same English fallback behavior.
local fallback = getmetatable(addon.L).__index
local localized = translations[addon.locale] or {}
for key, value in pairs(english) do
    fallback[key] = value
    addon.L[key] = localized[key] or value
end
